insert into public.missions (id, category, teaser, title, body, locale, is_active)
values
  ('a1f2e3d4-c5b6-4789-a012-345678010001'::uuid, 'social'::public.mission_category, 'There''s someone you only react to. Try words instead.', 'Mission: say something real', 'Open a chat with someone you usually only send emojis or likes to. Write one honest sentence about your day or theirs. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010003'::uuid, 'social'::public.mission_category, 'Someone in your contacts deserves a voice note.', 'Mission: send your voice', 'Record a short voice message for one person you trust. Keep it simple: a memory, a thank you, or a quick hello. You do not need to continue the conversation.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010004'::uuid, 'social'::public.mission_category, 'A familiar face is waiting for recognition.', 'Mission: acknowledge someone', 'Make eye contact with someone you see often but rarely speak to — a neighbor, cashier, receptionist, or barista. Say hello like you mean it. Stop there if you want.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010005'::uuid, 'social'::public.mission_category, 'Ask a question with no practical purpose.', 'Mission: ask something human', 'During your next conversation, ask someone what they''ve been enjoying lately. Don''t turn it into advice or recommendations. Just stay curious for two minutes.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010006'::uuid, 'social'::public.mission_category, 'A compliment is sitting unsent.', 'Mission: say the nice thing', 'Think of one specific thing you appreciate about someone. Tell them directly in one sentence. No extra explanation needed.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010008'::uuid, 'social'::public.mission_category, 'Call someone without needing anything.', 'Mission: unexpected call', 'Phone one person you usually only text. Keep the call under five minutes if you want. The point is hearing a voice.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010009'::uuid, 'social'::public.mission_category, 'There''s a tiny favor you can offer.', 'Mission: make life lighter', 'Ask someone nearby if they need help carrying, moving, or reaching something small. Accept yes or no without insisting. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010010'::uuid, 'social'::public.mission_category, 'One message can reopen a quiet friendship.', 'Mission: reopen the thread', 'Send a short message to someone you haven''t spoken to in months. Mention a memory or ask how they''ve been lately. You don''t need to explain the silence.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010012'::uuid, 'social'::public.mission_category, 'Your future self might remember this stranger.', 'Mission: ask for a recommendation', 'Ask someone nearby for a recommendation — a bakery item, a park, a movie, anything local and simple. Thank them and move on. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010013'::uuid, 'social'::public.mission_category, 'Sit closer to people today.', 'Mission: choose proximity', 'In a public place, sit near other people instead of automatically choosing the isolated corner. Stay present for a few minutes. No conversation required.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010014'::uuid, 'social'::public.mission_category, 'There''s a thank-you you forgot to send.', 'Mission: close the loop', 'Message someone who helped you recently, even in a small way. Be specific about what you appreciated. Stop after sending it.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010015'::uuid, 'social'::public.mission_category, 'Share a memory instead of an update.', 'Mission: bring something back', 'Text someone a memory you still laugh about or think about sometimes. Don''t add a photo or link. Just the moment itself.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010016'::uuid, 'social'::public.mission_category, 'You can make someone feel noticed in 10 seconds.', 'Mission: use their name', 'During your next interaction, say the person''s name out loud once if you know it. Keep the rest natural. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010017'::uuid, 'social'::public.mission_category, 'A tiny invitation counts.', 'Mission: ask someone along', 'Invite someone to join you for a very small thing today — a coffee run, short walk, or quick errand. Keep it low pressure. One ask is enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010018'::uuid, 'social'::public.mission_category, 'Be the first person to wave.', 'Mission: start the hello', 'When you pass someone familiar today, greet them before they greet you. Keep walking if you want afterward. Stop there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010019'::uuid, 'social'::public.mission_category, 'One honest answer could change the tone.', 'Mission: answer properly', 'The next time someone asks how you are, answer with one real sentence instead of autopilot. Nothing dramatic required. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010021'::uuid, 'social'::public.mission_category, 'Someone around you has a story you''ll never hear.', 'Mission: small curiosity', 'Ask a simple follow-up question during a casual interaction today. Stay with the answer instead of turning back to yourself immediately. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010022'::uuid, 'social'::public.mission_category, 'An old friend might answer faster than you think.', 'Mission: random check-in', 'Choose one person you haven''t thought about in a while. Send a short message asking what life has been like lately. Stop after pressing send.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010024'::uuid, 'social'::public.mission_category, 'You don''t need a reason to reach out.', 'Mission: send the first text', 'Start a conversation today without needing news, plans, or logistics. A simple "thought of you" is enough. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010025'::uuid, 'social'::public.mission_category, 'Notice who always initiates with you.', 'Mission: reverse the pattern', 'Think of someone who usually reaches out first. Contact them before they contact you this time. Keep it short and easy.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010032'::uuid, 'social'::public.mission_category, 'You already know more neighbors than you think.', 'Mission: hallway hello', 'If you cross paths with a neighbor today, pause for one extra sentence instead of a quick nod. Keep it casual and brief. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010033'::uuid, 'social'::public.mission_category, 'One person deserves your full attention for 2 minutes.', 'Mission: listen without fixing', 'During one conversation today, resist giving advice or turning the topic back to yourself. Just listen until the other person finishes. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010035'::uuid, 'social'::public.mission_category, 'A real laugh sounds better out loud.', 'Mission: share something funny', 'Tell someone about a genuinely funny thing that happened recently instead of sending a clip or meme. Keep it imperfect. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010036'::uuid, 'social'::public.mission_category, 'Notice who makes your days easier.', 'Mission: appreciate the regulars', 'Thank someone whose work quietly supports your routine — cleaner, driver, receptionist, cashier, delivery worker. Keep it direct and simple. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010037'::uuid, 'social'::public.mission_category, 'A question can change a whole mood.', 'Mission: ask about today', 'Ask someone what the best part of their day has been so far. Listen to the first answer without rushing onward. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010039'::uuid, 'social'::public.mission_category, 'There''s probably a local regular you recognize.', 'Mission: become familiar', 'Return to a place you visit sometimes and stay long enough for one brief interaction with the people there. Recognition counts. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010040'::uuid, 'social'::public.mission_category, 'Try one tiny act of trust.', 'Mission: ask for help', 'Ask someone for a small favor today — directions, an opinion, help opening something, a recommendation. Let them help if they want to. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010042'::uuid, 'social'::public.mission_category, 'Someone in your life needs encouragement.', 'Mission: back someone up', 'Send a message reminding someone that they''re doing better than they think at something specific. Keep it grounded and short. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010043'::uuid, 'social'::public.mission_category, 'You can change the energy of a room quietly.', 'Mission: arrive open', 'When entering a shared space today, look up instead of immediately disappearing into your own world. A smile or nod is enough. Stop there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010044'::uuid, 'social'::public.mission_category, 'Reconnect through a shared memory.', 'Mission: remember together', 'Message someone about a place, song, meal, or moment you both experienced. Let the memory sit without forcing a long conversation. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010046'::uuid, 'social'::public.mission_category, 'Someone would probably answer if you invited them.', 'Mission: make a simple plan', 'Invite one person to do something low-effort this week — coffee, lunch, a walk, browsing a shop. Keep the invitation casual. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010047'::uuid, 'social'::public.mission_category, 'Try noticing the quiet people.', 'Mission: include someone', 'During a group moment today, direct one question toward the quieter person in the room. Give them space to answer. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678010049'::uuid, 'social'::public.mission_category, 'Your attention is useful to someone.', 'Mission: notice effort', 'Tell someone you noticed a specific effort they made recently — cooking, organizing, showing up, helping, trying. Keep it sincere and brief. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020001'::uuid, 'nature'::public.mission_category, 'The sky is doing something right now.', 'Mission: look up', 'Step outside or find a window. Spend one minute looking only at the sky and notice three different shades or movements. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020002'::uuid, 'nature'::public.mission_category, 'There''s a tree you pass without seeing.', 'Mission: meet a tree', 'Find the nearest tree, even a tiny city one. Stand near it for 30 seconds and notice the shape of its bark or branches. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020003'::uuid, 'nature'::public.mission_category, 'Open a door. Hear the city differently.', 'Mission: sound check', 'Pause outside for two minutes without music or conversation. Count five separate sounds you can hear at the same time. You can head back in after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020004'::uuid, 'nature'::public.mission_category, 'The weather has a texture today.', 'Mission: feel the air', 'Step outside for one minute — even just the sidewalk outside your building. Pay attention to the air on your face and hands. Warm, damp, sharp, heavy — describe it silently to yourself. Stop there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020005'::uuid, 'nature'::public.mission_category, 'Find one living thing you usually ignore.', 'Mission: tiny life', 'Notice one small living thing nearby — moss, weeds, insects, pigeons, anything. Watch it closely for 60 seconds without taking a photo. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020006'::uuid, 'nature'::public.mission_category, 'Walk slower for exactly one block.', 'Mission: slower route', 'During your next walk, slow your pace for one block. Notice what changes when you stop rushing past the street around you. Stop after that block.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020007'::uuid, 'nature'::public.mission_category, 'There''s movement above you right now.', 'Mission: cloud watch', 'Look at the clouds for two minutes, even if there are only a few. Follow their direction and speed without doing anything else. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020008'::uuid, 'nature'::public.mission_category, 'Borrow five minutes from the evening light.', 'Mission: sunset pause', 'If the timing works today, step outside near sunset. Watch the light change on buildings, pavement, or faces for five quiet minutes. Head back in whenever you''re ready.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020009'::uuid, 'nature'::public.mission_category, 'The ground under you has details.', 'Mission: pavement study', 'Walk slowly for two minutes while looking down instead of ahead. Notice cracks, leaves, reflections, or patterns in the ground. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020011'::uuid, 'nature'::public.mission_category, 'Notice what survives in your neighborhood.', 'Mission: urban green', 'Find one patch of green nearby — a planter, balcony vine, park edge, anything. Spend a minute looking at how it fits into the street around it. Stop there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020013'::uuid, 'nature'::public.mission_category, 'Find the quietest outdoor spot nearby.', 'Mission: quiet corner', 'Walk until you find a slightly calmer outdoor spot — a bench, side street, courtyard, or corner. Stay there for three minutes and let the street noise settle around you. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020014'::uuid, 'nature'::public.mission_category, 'Something outside is reflecting light.', 'Mission: reflections', 'Look for reflections outdoors — puddles, windows, metal, sunglasses, anything. Spend two minutes noticing how light changes surfaces. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020015'::uuid, 'nature'::public.mission_category, 'Night air feels different.', 'Mission: step into night', 'Go outside after dark for five minutes if you can. Notice the sounds, temperature, and pace of the street at night compared to daytime. Head back in after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020016'::uuid, 'nature'::public.mission_category, 'Watch wind without looking at the wind.', 'Mission: moving things', 'Find something the wind is affecting — leaves, clothes, flags, hair, water. Watch the movement for one minute. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020017'::uuid, 'nature'::public.mission_category, 'Find one natural color today.', 'Mission: color search', 'Choose one color before stepping outside. Spend five minutes spotting that color in plants, sky, stone, water, or light around you. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020018'::uuid, 'nature'::public.mission_category, 'There are birds somewhere nearby.', 'Mission: listen for birds', 'Open a window or go outside for two minutes. Listen carefully for bird sounds hidden under the rest of the city noise. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020019'::uuid, 'nature'::public.mission_category, 'Sunlight lands differently every hour.', 'Mission: follow the light', 'Notice one patch of sunlight indoors or outside. Watch how it shifts or changes shape for a minute before moving on. Stop there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020020'::uuid, 'nature'::public.mission_category, 'Find water, even a tiny bit.', 'Mission: water nearby', 'Look for water around you — a fountain, puddle, river, rain gutter, coffee steam, anything. Spend one minute paying attention to how it moves. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020021'::uuid, 'nature'::public.mission_category, 'Take the slightly greener path.', 'Mission: detour through green', 'On your next short walk, choose the route with more trees or open sky, even if it''s only one extra minute. Notice how the space feels different. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020022'::uuid, 'nature'::public.mission_category, 'Stand still outside for longer than usual.', 'Mission: pause outdoors', 'Find a place outside to stand still for three minutes. Let people, bikes, clouds, and sounds move around you while you stay put. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020023'::uuid, 'nature'::public.mission_category, 'Morning air has its own personality.', 'Mission: early air', 'If you''re awake early enough, step outside for two minutes before the day fully starts. Notice what the street sounds like before it fills up. Head back in after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020024'::uuid, 'nature'::public.mission_category, 'Look for nature in the wrong places.', 'Mission: unexpected green', 'Find one natural thing growing or existing where it probably wasn''t planned to — cracks, walls, rooftops, fences. Give it a full minute of attention. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020025'::uuid, 'nature'::public.mission_category, 'The temperature changes block by block.', 'Mission: temperature map', 'During a short walk, notice where the air gets cooler, warmer, shaded, or windy. Pay attention for five minutes, then move on with your day.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020026'::uuid, 'nature'::public.mission_category, 'Touch something natural today.', 'Mission: texture check', 'Touch bark, stone, grass, leaves, or even rough concrete outside. Spend 30 seconds noticing texture instead of rushing past it. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020029'::uuid, 'nature'::public.mission_category, 'Notice shadows instead of objects.', 'Mission: shadow watch', 'Spend two minutes paying attention only to shadows outdoors. Watch how they stretch, overlap, or move as people and light shift around you. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678020030'::uuid, 'nature'::public.mission_category, 'There''s weather happening even on ordinary days.', 'Mission: today''s atmosphere', 'Step outside for one minute. Notice whether today feels heavy, bright, soft, restless, or clear — in the air, the light, the pace around you. Stop there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678901103'::uuid, 'nature'::public.mission_category, '30 seconds. No goal. Just look.', 'Mission: notice the outside', 'Go to a window or step outside for 30 seconds. Name one thing you never really noticed before — a sound, a shape, a color.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678901104'::uuid, 'nature'::public.mission_category, 'Touch something alive.', 'Mission: connect with the living world', 'Find a plant, a tree, grass, or a pet. Touch it gently. Take one slow breath while you do.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030001'::uuid, 'curiosity'::public.mission_category, 'There''s a story hiding in an ordinary object.', 'Mission: object detective', 'Choose one everyday object near you. Study it for two minutes and list three details you had never noticed before. Invent one question about how it came to be there. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030002'::uuid, 'curiosity'::public.mission_category, 'Ask a question you normally leave unasked.', 'Mission: one real question', 'The next time you speak with someone today, ask them about a hobby, skill, or routine they know well. Listen to the answer without changing the subject. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030003'::uuid, 'curiosity'::public.mission_category, 'A sound nearby deserves your attention.', 'Mission: follow a sound', 'Pause for one minute and notice a sound in your surroundings. Trace where it might be coming from and what could be creating it. When your curiosity feels satisfied, stop.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030004'::uuid, 'curiosity'::public.mission_category, 'One sign or label can open a rabbit hole.', 'Mission: read the fine print', 'Find a sign, label, plaque, or notice you usually ignore. Read every word. Notice one detail that changes how you see that place or object. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030005'::uuid, 'curiosity'::public.mission_category, 'Take a different route with your eyes.', 'Mission: look higher', 'Walk a short distance or look out a window. Spend two minutes noticing what is above eye level—roofs, branches, wires, clouds, or architecture. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030006'::uuid, 'curiosity'::public.mission_category, 'Something nearby has changed recently.', 'Mission: spot the difference', 'Look around a familiar room, street, yard, or path. Find one thing that wasn''t there before or has shifted since you last paid attention. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030008'::uuid, 'curiosity'::public.mission_category, 'Count something nobody usually counts.', 'Mission: unusual tally', 'Choose one thing around you—red doors, birds, parked bicycles, fence posts, or something else. Count them for two minutes. When the timer ends, you''re done.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030009'::uuid, 'curiosity'::public.mission_category, 'Your neighborhood has a tiny mystery.', 'Mission: trace a clue', 'Notice an object that seems out of place. Spend a few minutes imagining two possible explanations for how it got there. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030010'::uuid, 'curiosity'::public.mission_category, 'Look for evidence of a hidden process.', 'Mission: behind the scenes', 'Find something being maintained, repaired, grown, cleaned, built, or organized. Observe it closely for a minute. Notice signs of the work behind it. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030011'::uuid, 'curiosity'::public.mission_category, 'One shelf can teach you something.', 'Mission: inspect a shelf', 'Choose a shelf, cupboard, drawer, or storage space. Pick one item and wonder why it was kept. Follow that question for a few minutes, then stop.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030012'::uuid, 'curiosity'::public.mission_category, 'Notice what repeats.', 'Mission: find a pattern', 'Look around your environment and identify a repeating shape, sound, color, or behavior. Spend two minutes tracking where else it appears. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030013'::uuid, 'curiosity'::public.mission_category, 'A place you know has an overlooked corner.', 'Mission: explore the edge', 'Visit a familiar room, yard, hallway, or outdoor spot. Pay attention to the least-noticed corner for three minutes. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030014'::uuid, 'curiosity'::public.mission_category, 'Borrow someone else''s perspective.', 'Mission: ask for a favorite', 'Ask someone to tell you their favorite local place, object, view, or routine. Learn why they chose it. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030015'::uuid, 'curiosity'::public.mission_category, 'Something old still has a secret.', 'Mission: date an object', 'Find an older item in your home or surroundings. Look for clues about when it was made or first used. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030016'::uuid, 'curiosity'::public.mission_category, 'Change one angle. See what appears.', 'Mission: new viewpoint', 'Stand, sit, or crouch somewhere you usually pass through. Spend one minute observing from that different height. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030017'::uuid, 'curiosity'::public.mission_category, 'What happens here when you''re not looking?', 'Mission: imagine the timeline', 'Choose a place nearby. Picture what it looked like five years ago and what it might look like five years from now. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030018'::uuid, 'curiosity'::public.mission_category, 'Read a name and wonder about it.', 'Mission: notice names', 'Look for a street name, building name, product name, or family name. Spend a few minutes guessing the story behind it before moving on. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030021'::uuid, 'curiosity'::public.mission_category, 'Your hands know more than your eyes.', 'Mission: texture survey', 'Carefully touch three different surfaces around you. Compare their textures and notice which details are easiest to miss visually. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030022'::uuid, 'curiosity'::public.mission_category, 'A routine path has a missing detail.', 'Mission: reverse attention', 'Walk a familiar route and look for what you normally ignore rather than what usually catches your eye. Notice three things. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030023'::uuid, 'curiosity'::public.mission_category, 'Look for evidence, not answers.', 'Mission: tiny investigation', 'Choose a mark, track, crack, stain, or worn spot. Spend two minutes imagining what repeated action created it. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030024'::uuid, 'curiosity'::public.mission_category, 'The weather is doing more than you think.', 'Mission: weather clues', 'Step outside or look through a window. Find three signs of today''s weather besides temperature. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030025'::uuid, 'curiosity'::public.mission_category, 'Find the oldest thing you can see.', 'Mission: age hunt', 'Look around your surroundings and choose the object, structure, or tree that seems oldest. Notice the clues that led you there. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030026'::uuid, 'curiosity'::public.mission_category, 'One minute of listening can reveal a map.', 'Mission: sound map', 'Close your eyes for sixty seconds. Identify as many distinct sounds as you can and imagine where each one is coming from. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030028'::uuid, 'curiosity'::public.mission_category, 'Ask about a first time.', 'Mission: first memories', 'Talk with someone and ask about the first time they learned, tried, or experienced something important to them. Listen to the story. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030029'::uuid, 'curiosity'::public.mission_category, 'Choose a direction you rarely notice.', 'Mission: look behind you', 'Turn around and study the space behind where you usually sit, stand, or wait. Spend one minute noticing details you normally miss. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678030030'::uuid, 'curiosity'::public.mission_category, 'There''s a question hiding in plain sight.', 'Mission: wonder aloud', 'Write down one question about something you encounter today. Don''t answer it yet. Let the question exist for a few minutes, then move on.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040001'::uuid, 'adventure'::public.mission_category, 'There''s a street you always ignore.', 'Mission: the unfamiliar turn', 'The next time you head somewhere nearby, take one street, path, or lane you normally ignore. Follow it for a few minutes and notice what changes. Turn back whenever you like. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040002'::uuid, 'adventure'::public.mission_category, 'Efficiency can wait one block.', 'Mission: route detour', 'While walking, add a small loop to your usual route. Stay curious instead of efficient. Stop after one extra block, bend, or stretch of road.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040003'::uuid, 'adventure'::public.mission_category, 'Same place. Different entrance.', 'Mission: new doorway', 'Visit a familiar place and enter from a different side or approach if possible. Notice what catches your attention first. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040004'::uuid, 'adventure'::public.mission_category, 'Left, right, or straight — then go.', 'Mission: follow a direction', 'Step outside or to a window. Choose left, right, or straight without overthinking it, then explore that direction for five minutes. Head back whenever you''re ready.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040005'::uuid, 'adventure'::public.mission_category, 'Something in the distance is worth reaching.', 'Mission: chase a landmark', 'Spot something in the distance—a tree, roofline, fence, hill, or sign. Move toward it if it''s safely reachable nearby. Once you arrive, you''re done.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040006'::uuid, 'adventure'::public.mission_category, 'Walk half as fast for three minutes.', 'Mission: slower than usual', 'Walk more slowly than you normally would for three minutes. Let details appear that usually blur past. Return to your normal pace after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040007'::uuid, 'adventure'::public.mission_category, 'Stand somewhere you never choose.', 'Mission: new vantage point', 'Find a spot nearby where you don''t usually stand—another corner of a yard, a different bench, the far side of a room. Stay there for two minutes and take in the scene. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040009'::uuid, 'adventure'::public.mission_category, 'See a familiar place at an unusual hour.', 'Mission: different timing', 'Visit a nearby spot you know well at a time you don''t usually see it. Notice how the light, sounds, or activity differ. Stay only a few minutes.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040010'::uuid, 'adventure'::public.mission_category, 'No destination — only what pulls you.', 'Mission: follow curiosity', 'Start moving with no destination beyond your immediate area. When something genuinely catches your attention, go closer and examine it for a minute. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040011'::uuid, 'adventure'::public.mission_category, 'Your everyday room still has surprises.', 'Mission: indoor expedition', 'Choose a room you use every day. Spend five minutes noticing corners, shelves, or objects you''ve stopped seeing. End when you''ve found three surprises.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040012'::uuid, 'adventure'::public.mission_category, 'Ten minutes with nowhere to be.', 'Mission: no destination', 'Head outside or into a shared space without a plan. Let each small decision come from whatever interests you next. Stop after ten minutes.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040013'::uuid, 'adventure'::public.mission_category, 'Find something older than everything else.', 'Mission: time traveler', 'Look around your surroundings and search for something that seems older than everything else nearby. Spend a moment imagining what it has witnessed. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040014'::uuid, 'adventure'::public.mission_category, 'Ask the place what''s most interesting.', 'Mission: ask the place', 'Wherever you are, ask yourself: ''What''s the most interesting thing here?'' Go investigate your answer. Stop after a few minutes.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040015'::uuid, 'adventure'::public.mission_category, 'Step from one world into another nearby.', 'Mission: cross over', 'Move from one environment into another nearby: indoors to outdoors, pavement to grass, busy to quiet, sun to shade. Notice the shift. Stay with it for a minute.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040017'::uuid, 'adventure'::public.mission_category, 'Take the long way on purpose.', 'Mission: scenic version', 'Choose the less direct option for a short trip nearby. Pay attention to what appears because you weren''t rushing. Return to normal after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040018'::uuid, 'adventure'::public.mission_category, 'Wander until somewhere makes you stop.', 'Mission: pause point', 'Wander until you find a spot that makes you want to stop for thirty seconds. Stand there and take in the surroundings. Then continue or head home.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040019'::uuid, 'adventure'::public.mission_category, 'Walk to the edge of your usual map.', 'Mission: edge of familiar', 'Go to the furthest point nearby that still feels part of your everyday territory. Spend two minutes there. Turn back after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040020'::uuid, 'adventure'::public.mission_category, 'Somewhere you haven''t been in a while.', 'Mission: revisit briefly', 'Return to a place you haven''t visited in a while but can reach easily. Compare it with your memory. Stay only a few minutes.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040021'::uuid, 'adventure'::public.mission_category, 'Follow a sound until you''ve found it.', 'Mission: sound trail', 'Notice a distant sound—a bird, machinery, voices, wind, or water. Move toward it if practical and safe. Stop when you''ve located the source or satisfied your curiosity.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040022'::uuid, 'adventure'::public.mission_category, 'Change your height for a new view.', 'Mission: higher or lower', 'Find a nearby spot slightly higher or lower than where you are now. Spend a moment observing from that new perspective. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040024'::uuid, 'adventure'::public.mission_category, 'Inspect something you always pass.', 'Mission: object expedition', 'Choose one object you pass often outdoors or in a shared space. Walk over and inspect it more closely than usual. End once you''ve noticed three details.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040025'::uuid, 'adventure'::public.mission_category, 'Sit where you never sit.', 'Mission: different seat', 'Sit somewhere you don''t normally choose—a different chair, bench, step, or patch of ground. Stay for three minutes and watch the world from there. Then move on.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040026'::uuid, 'adventure'::public.mission_category, 'Find a bend and see what''s past it.', 'Mission: follow the curve', 'Seek out a winding path, road, hallway, or trail nearby. Follow it until the next bend or turn. Stop after seeing what''s around it.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040027'::uuid, 'adventure'::public.mission_category, 'Match someone''s walking rhythm for one minute.', 'Mission: match the rhythm', 'Observe the pace of someone walking nearby, or imagine one if you''re alone. Match that rhythm for one minute. Return to your own pace after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040028'::uuid, 'adventure'::public.mission_category, 'Pick the smallest visible target.', 'Mission: tiny destination', 'Choose something small you can see nearby—a flower, mailbox, stone, post, or gate. Make it your destination. Once you reach it, you''re done.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040029'::uuid, 'adventure'::public.mission_category, 'Two minutes inside one square meter.', 'Mission: one-square-meter safari', 'Focus on a very small area around you, indoors or outdoors. Search it as if you''re seeing it for the first time. Stop after two minutes.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678040030'::uuid, 'adventure'::public.mission_category, 'Close the gap on something you''ve only seen from afar.', 'Mission: close the distance', 'Notice something you''ve only ever seen from afar in your area. Walk closer and examine it for a minute. That''s enough for today.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050001'::uuid, 'creativity'::public.mission_category, 'A receipt, envelope, or scrap is enough.', 'Mission: tiny collage', 'Find three small scraps of paper from around you. Arrange them into a picture, pattern, or scene on a table. Change it once, then leave it. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050002'::uuid, 'creativity'::public.mission_category, 'Give an ordinary object a secret history.', 'Mission: object backstory', 'Choose one object within reach. Invent a three-sentence story about where it came from before it reached you. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050003'::uuid, 'creativity'::public.mission_category, 'Your voice can make something no one else can.', 'Mission: hum a soundtrack', 'Look out a window or around the room. Hum a short soundtrack for what you see, even if it sounds strange. Let it last one minute. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050004'::uuid, 'creativity'::public.mission_category, 'Turn five words into something unexpected.', 'Mission: five-word poem', 'Pick five random words from signs, packaging, or memory. Arrange them into the shortest poem you can. Read it once and stop.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050005'::uuid, 'creativity'::public.mission_category, 'Draw without looking down.', 'Mission: blind sketch', 'Choose a nearby object. Draw its outline without looking at the page while your hand moves. When you''re done, put the pen down. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050006'::uuid, 'creativity'::public.mission_category, 'One sound is waiting to become music.', 'Mission: kitchen rhythm', 'Tap two household items gently and listen to the different tones. Create a simple rhythm that lasts ten seconds. Repeat it once, then stop.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050007'::uuid, 'creativity'::public.mission_category, 'A shadow can become a picture.', 'Mission: trace a shape', 'Find an interesting shadow or outline nearby. Trace it on paper or in the air with your finger. Add one detail and finish there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050008'::uuid, 'creativity'::public.mission_category, 'Borrow a color from the world around you.', 'Mission: color hunt', 'Notice one color that appears at least three times around you. Make a quick list or sketch inspired by it. Stop after the third example.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050009'::uuid, 'creativity'::public.mission_category, 'Tell a story in exactly three lines.', 'Mission: three-line tale', 'Write a beginning, middle, and end using only one line each. Keep it simple. When the third line is done, you''re finished.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050010'::uuid, 'creativity'::public.mission_category, 'Rearrange something for beauty, not function.', 'Mission: tabletop composition', 'Gather three nearby objects. Arrange them into a display that pleases you for any reason at all. Look at it for a moment, then move on.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050011'::uuid, 'creativity'::public.mission_category, 'Name something that doesn''t need a name.', 'Mission: invent a name', 'Choose a tree, rock, cloud, chair, or other ordinary thing. Give it a name that feels right. Use the name in one sentence. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050012'::uuid, 'creativity'::public.mission_category, 'Make a postcard no one will send.', 'Mission: imaginary postcard', 'Imagine you''re somewhere else for a day. Write two sentences for a postcard from that place. Stop after signing it with any name you like.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050013'::uuid, 'creativity'::public.mission_category, 'A leaf, stone, or twig can be a tool.', 'Mission: natural pattern', 'If you''re outdoors, collect one small natural object from the ground. Use it to create a temporary pattern or arrangement. Leave it there and continue your day.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050014'::uuid, 'creativity'::public.mission_category, 'Describe a sound without naming it.', 'Mission: sound portrait', 'Listen for a nearby sound. Describe it using shapes, textures, or weather instead of its actual source. Stop after three descriptions.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050015'::uuid, 'creativity'::public.mission_category, 'Make a map that won''t help anyone navigate.', 'Mission: memory map', 'Sketch a rough map of a room, garden, street, or place you know well. Include one detail from memory that matters only to you. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050016'::uuid, 'creativity'::public.mission_category, 'Turn today''s weather into a character.', 'Mission: weather character', 'Imagine the current weather as a person. Give them one habit and one goal. Leave the story there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050017'::uuid, 'creativity'::public.mission_category, 'One minute. One continuous line.', 'Mission: single-line drawing', 'Put pen to paper and draw without lifting it. Let the line wander into anything it becomes. Stop after one minute.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050018'::uuid, 'creativity'::public.mission_category, 'Make up a tiny celebration.', 'Mission: invent a holiday', 'Create a holiday for something ordinary, like rain on a roof or finding a lost button. Decide how people celebrate it in one sentence. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050019'::uuid, 'creativity'::public.mission_category, 'The next object you notice has a role to play.', 'Mission: cast the object', 'Notice the first object that catches your attention. Imagine it as a character in a film or novel. Give it one line of dialogue and stop.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050020'::uuid, 'creativity'::public.mission_category, 'Build something that lasts five minutes.', 'Mission: temporary sculpture', 'Use coins, stones, blocks, paper, or similar items nearby. Create a small sculpture. Leave it up briefly, then let it go.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050021'::uuid, 'creativity'::public.mission_category, 'Collect details, not things.', 'Mission: texture inventory', 'Find four different textures around you. Describe each in a few words on paper or out loud. Stop after the fourth.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050022'::uuid, 'creativity'::public.mission_category, 'A conversation starter for yourself.', 'Mission: curious question', 'Write a question you don''t know the answer to and aren''t trying to solve today. Add one possible answer just for fun. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050023'::uuid, 'creativity'::public.mission_category, 'Create a title before the artwork exists.', 'Mission: title first', 'Invent a title for a painting, song, or book that doesn''t exist. Then spend two minutes imagining it. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050024'::uuid, 'creativity'::public.mission_category, 'Change one familiar phrase.', 'Mission: remix a saying', 'Think of a common saying or expression. Replace one word and see what happens. Keep the version you like best and move on.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050025'::uuid, 'creativity'::public.mission_category, 'Look up. There''s material there.', 'Mission: cloud or ceiling story', 'Study a cloud, ceiling pattern, or patch of light. Imagine a scene hidden inside it. Describe the scene in two sentences. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050026'::uuid, 'creativity'::public.mission_category, 'Make something together in under two minutes.', 'Mission: shared invention', 'If someone is nearby, take turns adding one sentence to an imaginary story. Stop after six sentences total. If you''re alone, play both roles.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050027'::uuid, 'creativity'::public.mission_category, 'Design a symbol for today.', 'Mission: personal emblem', 'Draw a simple symbol that captures how today feels so far. It can be abstract or literal. When it feels complete, stop.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050028'::uuid, 'creativity'::public.mission_category, 'One object. Three uses it never had.', 'Mission: alternate purposes', 'Choose a nearby object. Invent three completely different uses for it, no matter how impractical. Stop after the third idea.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050029'::uuid, 'creativity'::public.mission_category, 'Write a note from a future afternoon.', 'Mission: future message', 'Imagine yourself one month from now. Write a short note back to today. Keep it to three sentences or fewer. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678050030'::uuid, 'creativity'::public.mission_category, 'Find beauty in repetition.', 'Mission: repeating pattern', 'Notice a repeating pattern nearby: bricks, fence posts, tiles, branches, or something else. Sketch or describe it in your own style. Stop after a few minutes.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678901108'::uuid, 'creativity'::public.mission_category, 'Make something small, just for you.', 'Mission: a 5-minute creation', 'For five minutes, make something with your hands — doodle, fold paper, hum a melody, rearrange a corner of your space. No posting required.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678901109'::uuid, 'calm'::public.mission_category, 'Silence is not empty.', 'Mission: give your brain quiet', 'Sit or stand still for two minutes without a podcast, video, or feed. Hear the room. Let your mind drift without grabbing new input.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060001'::uuid, 'calm'::public.mission_category, 'A chair, a window, two quiet minutes.', 'Mission: window pause', 'Sit near a window or step outside. Spend two minutes watching light, shadow, or movement without naming tasks to do. When the two minutes are up, stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060002'::uuid, 'calm'::public.mission_category, 'Listen until you find the farthest sound.', 'Mission: distant listening', 'Stay still for one minute. Notice the closest sound you can hear, then the farthest. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060003'::uuid, 'calm'::public.mission_category, 'Your hands know this already.', 'Mission: warm mug', 'Hold a mug, cup, or glass with both hands. Notice its temperature and weight for 30 seconds. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060004'::uuid, 'calm'::public.mission_category, 'Find three shades of the same color.', 'Mission: color hunt', 'Look around the room or outside. Find three different shades of one color and let your eyes rest on each for a moment. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060005'::uuid, 'calm'::public.mission_category, 'Stand where you are and do less.', 'Mission: still feet', 'Stand or sit without adjusting your position for one minute. Feel where your body meets the floor, chair, or ground. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060006'::uuid, 'calm'::public.mission_category, 'Open a door. Not to leave.', 'Mission: fresh air moment', 'Open a window or step outside briefly. Take ten slow breaths while noticing the temperature of the air. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060007'::uuid, 'calm'::public.mission_category, 'One object deserves a closer look.', 'Mission: quiet inspection', 'Choose an ordinary object nearby. Spend two minutes noticing details you usually ignore. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060008'::uuid, 'calm'::public.mission_category, 'No destination. Just a slower pace.', 'Mission: slow walk', 'Walk for five minutes at a slightly slower pace than usual. Let your attention settle on your surroundings rather than your plans. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060009'::uuid, 'calm'::public.mission_category, 'The room has a soundtrack.', 'Mission: room orchestra', 'Pause whatever you''re doing. Listen for five different sounds in the space around you. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060010'::uuid, 'calm'::public.mission_category, 'Look up for thirty seconds.', 'Mission: ceiling and sky', 'Wherever you are, direct your gaze upward. Notice shapes, textures, clouds, beams, or branches overhead. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060011'::uuid, 'calm'::public.mission_category, 'Nothing to solve for the next minute.', 'Mission: one-minute drift', 'Sit comfortably and let your thoughts wander for sixty seconds. No notes, no plans, no corrections. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060012'::uuid, 'calm'::public.mission_category, 'Find the softest thing nearby.', 'Mission: texture break', 'Touch a fabric, leaf, blanket, or other surface. Spend a minute noticing its texture without rushing. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060013'::uuid, 'calm'::public.mission_category, 'A tiny reset hides in plain sight.', 'Mission: tidy one spot', 'Clear or straighten a space no larger than a dinner plate. Pause and look at it when you''re done. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060014'::uuid, 'calm'::public.mission_category, 'The weather has a detail for you.', 'Mission: weather notice', 'Step outside or look through a window. Identify one thing the weather is doing right now. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060015'::uuid, 'calm'::public.mission_category, 'Try a quieter version of a routine.', 'Mission: silent sip', 'Have a drink of water, tea, or coffee without reading, watching, or multitasking. Pay attention only to the experience. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060016'::uuid, 'calm'::public.mission_category, 'One corner of the world, fully noticed.', 'Mission: corner study', 'Choose a small corner of a room, yard, porch, or street view. Observe it for two minutes as if seeing it for the first time. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060017'::uuid, 'calm'::public.mission_category, 'Borrow calm from a tree or a wall.', 'Mission: lean and pause', 'Lean against something steady: a wall, fence, railing, or tree. Stay there for one minute and feel the support beneath you. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060018'::uuid, 'calm'::public.mission_category, 'There is a rhythm nearby.', 'Mission: find a pattern', 'Listen or look for something repeating: footsteps, wind, a clock, distant traffic, birdsong. Follow that pattern for a minute. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060019'::uuid, 'calm'::public.mission_category, 'A seat with no agenda.', 'Mission: sit outside', 'If you can, sit outdoors for five minutes. Let the environment come to you instead of seeking stimulation. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060020'::uuid, 'calm'::public.mission_category, 'One deep exhale changes the pace.', 'Mission: longer exhale', 'Take five slow breaths. Let each exhale last a little longer than the inhale. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060021'::uuid, 'calm'::public.mission_category, 'Watch movement you didn''t create.', 'Mission: moving world', 'Spend two minutes observing something in motion: leaves, clouds, shadows, water, people, or animals. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060022'::uuid, 'calm'::public.mission_category, 'The next minute belongs to your senses.', 'Mission: sensory check-in', 'Notice one thing you can see, hear, feel, and smell. Move slowly through each sense. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060023'::uuid, 'calm'::public.mission_category, 'A quiet view is waiting somewhere nearby.', 'Mission: change vantage point', 'Move to a different seat, doorway, porch, or patch of ground. Spend three minutes taking in the view from there. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060025'::uuid, 'calm'::public.mission_category, 'Find the calmest sound around you.', 'Mission: sound anchor', 'Choose one steady sound and keep your attention on it for sixty seconds. When your mind wanders, gently return. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060026'::uuid, 'calm'::public.mission_category, 'Rest your eyes farther away.', 'Mission: long-distance gaze', 'Look toward the horizon, a distant building, a field, or the far end of a street. Keep your gaze there for a minute. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060027'::uuid, 'calm'::public.mission_category, 'A pause between tasks can be a place.', 'Mission: doorway pause', 'Before entering your next room or activity, stop in the doorway for ten seconds. Notice where you are before moving on. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060028'::uuid, 'calm'::public.mission_category, 'Notice what is already supporting you.', 'Mission: points of contact', 'Sit or stand comfortably. Spend a minute noticing every place your body touches something else. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060029'::uuid, 'calm'::public.mission_category, 'The world keeps moving without instructions.', 'Mission: watch and wait', 'Choose a spot outdoors or by a window. Observe whatever passes through it for three minutes without judging or tracking time. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678060030'::uuid, 'calm'::public.mission_category, 'One small pocket of quiet.', 'Mission: close your eyes', 'Close your eyes for thirty seconds in a safe place. Listen carefully and notice what arrives when sight steps back. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678901110'::uuid, 'learning'::public.mission_category, 'One skill, tiny step.', 'Mission: micro-practice', 'Pick something you’ve wanted to learn. Do exactly one tiny practice — one chord, one sentence, one stretch, one line read aloud. Stop after that one step.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070001'::uuid, 'learning'::public.mission_category, 'Borrow one word from a different world.', 'Mission: learn a new word', 'Ask someone, read a sign, or open a book to find one word you don''t know well. Learn what it means and say it out loud once. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070002'::uuid, 'learning'::public.mission_category, 'Your memory gets one small challenge today.', 'Mission: remember three', 'Look around and choose three objects. Study them for 30 seconds, then turn away and recall as many details as you can. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070003'::uuid, 'learning'::public.mission_category, 'Steal a tiny skill from someone nearby.', 'Mission: ask how', 'Find someone you can talk to and ask how they do a simple task well. Listen without interrupting. Thank them and stop there.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070004'::uuid, 'learning'::public.mission_category, 'Ten minutes with a thing you''ve never noticed.', 'Mission: inspect an object', 'Choose an everyday object and examine it closely. Notice marks, materials, or features you''ve never paid attention to before. Stop after five minutes if you like.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070005'::uuid, 'learning'::public.mission_category, 'Teach your future self one fact.', 'Mission: leave a note', 'Learn one new fact from a book, label, conversation, or sign. Write it on a scrap of paper in your own words. That''s enough for today.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070006'::uuid, 'learning'::public.mission_category, 'A sound is waiting to be identified.', 'Mission: name that sound', 'Spend two minutes listening. Pick one sound you can''t immediately place and investigate what makes it. Stop once you''ve learned something new.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070007'::uuid, 'learning'::public.mission_category, 'One sentence can become a lesson.', 'Mission: summarize a page', 'Read a single page from any book, magazine, or leaflet. Capture its main idea in one sentence from memory. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070008'::uuid, 'learning'::public.mission_category, 'There''s a skill hiding in your hands.', 'Mission: switch hands', 'Do one simple task with your non-dominant hand: stirring, brushing, opening a drawer, or similar. Notice what feels different. Stop after a few minutes.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070009'::uuid, 'learning'::public.mission_category, 'Learn the name of something living.', 'Mission: identify a neighbor', 'Find a tree, flower, bird, or plant nearby. Learn its name from a sign, a book, or someone who knows. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070010'::uuid, 'learning'::public.mission_category, 'One question. One real answer.', 'Mission: ask an elder', 'Talk with someone older than you, if available. Ask what skill they used to rely on a lot in the past but use much less today. Listen to their answer without interrupting. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070011'::uuid, 'learning'::public.mission_category, 'A map you already know has a gap in it.', 'Mission: redraw a route', 'From memory, sketch the route to a place you visit often. Compare it to reality the next time you travel it. Stop after the sketch.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070012'::uuid, 'learning'::public.mission_category, 'Can you explain it in one breath?', 'Mission: explain simply', 'Choose something you know well. Explain it out loud as if speaking to a curious twelve-year-old. Stop when you reach one minute.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070013'::uuid, 'learning'::public.mission_category, 'Your eyes know more than you think.', 'Mission: spot five patterns', 'Walk through a room, street, garden, or field. Find five repeating shapes, colors, or textures. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070014'::uuid, 'learning'::public.mission_category, 'Borrow a phrase from another language.', 'Mission: learn a phrase', 'Ask someone or look up a simple greeting in a language you don''t speak. Say it three times. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070015'::uuid, 'learning'::public.mission_category, 'A label can teach more than it seems.', 'Mission: read the fine print', 'Pick an item in your home and read the small print you usually ignore. Learn one detail about where it came from or how it''s made. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070016'::uuid, 'learning'::public.mission_category, 'Today, practice noticing cause and effect.', 'Mission: follow a chain', 'Observe something happening around you. Trace it back through three possible causes. Stop once you''ve built the chain.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070017'::uuid, 'learning'::public.mission_category, 'Learn one thing a place is trying to tell you.', 'Mission: read a sign', 'Find a public sign, notice board, or information plaque. Read it slowly and remember one detail. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070018'::uuid, 'learning'::public.mission_category, 'Your voice can be a study tool.', 'Mission: repeat and recall', 'Read a short paragraph aloud. Put it away and repeat the main idea from memory. Stop after one attempt.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070019'::uuid, 'learning'::public.mission_category, 'A stranger''s expertise might be nearby.', 'Mission: ask one question', 'If you meet someone working on a task today, ask a respectful question about it. Learn one thing you didn''t know before. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070020'::uuid, 'learning'::public.mission_category, 'Turn observation into a tiny field study.', 'Mission: count something', 'Choose something visible around you—birds, parked vehicles, fence posts, clouds, or footsteps. Count for two minutes and notice any pattern. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070021'::uuid, 'learning'::public.mission_category, 'One recipe, tool, or object has a history.', 'Mission: trace an origin', 'Pick an everyday item nearby. Learn where it was made or where the idea came from. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070022'::uuid, 'learning'::public.mission_category, 'Practice a skill for less time than you think.', 'Mission: two-minute practice', 'Spend exactly two minutes on a skill you already care about: drawing, singing, balancing, handwriting, or another favorite. Stop when the timer ends.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070023'::uuid, 'learning'::public.mission_category, 'Memory likes details more than effort.', 'Mission: notice three details', 'Look at a photograph, painting, or view outside. Find three details you missed at first glance. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070024'::uuid, 'learning'::public.mission_category, 'A household object has instructions worth reading.', 'Mission: learn a function', 'Choose a tool, appliance, or gadget you already own. Discover one feature you''ve never used or understood. Stop after learning it.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070025'::uuid, 'learning'::public.mission_category, 'Learn by comparing, not collecting facts.', 'Mission: find a difference', 'Place two similar objects side by side. Compare them carefully and list three differences. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070026'::uuid, 'learning'::public.mission_category, 'There''s a lesson in the weather today.', 'Mission: read the sky', 'Step outside or look through a window. Notice the clouds, light, or wind and make one prediction about the next hour. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070027'::uuid, 'learning'::public.mission_category, 'Learn a name, not just a face.', 'Mission: remember someone', 'If you meet someone today, make a deliberate effort to remember their name. Repeat it once in conversation. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070028'::uuid, 'learning'::public.mission_category, 'One forgotten fact is waiting on a shelf.', 'Mission: open a reference', 'Pick up a dictionary, handbook, guide, or reference book if you have one nearby. Open to a random page and learn one thing. Stop after that.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070029'::uuid, 'learning'::public.mission_category, 'Make a prediction before you know.', 'Mission: guess first', 'Before checking an answer, estimate it: distance, age, quantity, or time. Then compare your guess with reality. That''s enough.', 'en', true),
  ('a1f2e3d4-c5b6-4789-a012-345678070030'::uuid, 'learning'::public.mission_category, 'Learn something from where you already are.', 'Mission: study the room', 'Pause wherever you are. Find one object, one sound, and one texture you''ve overlooked until now. Stop after noticing all three.', 'en', true)
